import { useEffect } from 'react'
import { AnimatePresence, motion } from 'framer-motion'
import { AlertTriangle, RefreshCw } from 'lucide-react'
import AppShell from './components/AppShell'
import PlayerModal from './components/PlayerModal'
import ToastStack from './components/ToastStack'
import { useGame, VIEWS } from './context/GameContext'
import Dashboard from './views/Dashboard'
import Squad from './views/Squad'
import Tactics from './views/Tactics'
import MatchDay from './views/MatchDay'
import Transfers from './views/Transfers'
import Facilities from './views/Facilities'
import League from './views/League'

const VIEW_COMPONENTS = {
  dashboard: Dashboard,
  squad: Squad,
  tactics: Tactics,
  matchday: MatchDay,
  transfers: Transfers,
  facilities: Facilities,
  league: League
}

function Splash() {
  return (
    <div className="relative flex min-h-[100dvh] flex-col items-center justify-center overflow-hidden bg-ink-950 px-6">
      <div className="pointer-events-none absolute inset-0 bg-[radial-gradient(ellipse_50%_40%_at_50%_10%,rgba(201,247,92,0.14),transparent_65%)]" />
      <div className="pointer-events-none absolute inset-0 opacity-[0.025]" style={{ backgroundImage: 'linear-gradient(rgba(255,255,255,0.6) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,0.6) 1px, transparent 1px)', backgroundSize: '52px 52px' }} />
      <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} className="relative flex flex-col items-center">
        <div className="relative mb-6 flex h-16 w-16 items-center justify-center rounded-2xl bg-lime shadow-lime-lg">
          <svg viewBox="0 0 24 24" className="h-9 w-9 text-ink-950" fill="none" stroke="currentColor" strokeWidth="1.7">
            <rect x="3.2" y="4.2" width="17.6" height="15.6" rx="2" />
            <line x1="12" y1="4.2" x2="12" y2="19.8" />
            <circle cx="12" cy="12" r="2.6" />
            <path d="M3.2 8.2h4.2v7.6H3.2M20.8 8.2h-4.2v7.6h4.2" />
          </svg>
          <span className="absolute inset-0 animate-ping rounded-2xl border border-lime/30" style={{ animationDuration: '2.4s' }} />
        </div>
        <p className="display-title text-4xl tracking-[0.08em]">TOUCHLINE<span className="ml-1 text-lime">'26</span></p>
        <p className="mt-1 text-[9px] font-semibold uppercase tracking-[0.32em] text-mist-dim">Football Manager</p>
        <div className="mt-8 h-1 w-48 overflow-hidden rounded-full bg-white/[0.07]">
          <motion.div initial={{ x: '-100%' }} animate={{ x: '100%' }} transition={{ repeat: Infinity, duration: 1.3, ease: 'easeInOut' }} className="h-full w-1/2 rounded-full bg-lime" />
        </div>
        <p className="mt-3 text-[10px] text-mist-dim">Preparing the dressing room…</p>
      </motion.div>
    </div>
  )
}

function ErrorScreen() {
  const { error, refresh } = useGame()
  return (
    <div className="flex min-h-[100dvh] items-center justify-center bg-ink-950 p-6">
      <div className="panel w-full max-w-md p-7 text-center">
        <div className="mx-auto mb-4 flex h-12 w-12 items-center justify-center rounded-full bg-red-400/10 text-red-300">
          <AlertTriangle size={22} />
        </div>
        <h1 className="display-title text-2xl">The dressing room is locked</h1>
        <p className="mt-2 text-sm text-mist">We couldn’t reach the Touchline API. Check that the server is running and try again.</p>
        <p className="mt-3 rounded-lg border border-white/[0.06] bg-ink-950/60 p-2.5 text-[10px] text-mist-dim">{error?.message || 'Unknown connection error'}</p>
        <button onClick={() => refresh()} className="btn-primary mt-5 w-full">
          <RefreshCw size={15} /> Try again
        </button>
      </div>
    </div>
  )
}

export default function App() {
  const { data, loading, error, view } = useGame()
  const ViewComponent = VIEW_COMPONENTS[view] || Dashboard
  const current = VIEWS.find(item => item.id === view)

  useEffect(() => {
    document.title = `Touchline '26 · ${current?.label || 'Football Manager'}`
  }, [current?.label])

  if (loading && !data) return <Splash />
  if (error && !data) return <ErrorScreen />
  if (!data) return <Splash />

  return (
    <>
      <AppShell>
        <AnimatePresence mode="wait">
          <motion.div
            key={view}
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -6 }}
            transition={{ duration: 0.25, ease: [0.22, 1, 0.36, 1] }}
          >
            <ViewComponent />
          </motion.div>
        </AnimatePresence>
      </AppShell>
      <PlayerModal />
      <ToastStack />
    </>
  )
}
import React from 'react'
import ReactDOM from 'react-dom/client'
import '@fontsource/barlow-condensed/latin-500.css'
import '@fontsource/barlow-condensed/latin-600.css'
import '@fontsource/barlow-condensed/latin-700.css'
import '@fontsource/manrope/latin-400.css'
import '@fontsource/manrope/latin-500.css'
import '@fontsource/manrope/latin-600.css'
import '@fontsource/manrope/latin-700.css'
import '@fontsource/manrope/latin-800.css'
import './index.css'
import App from './App.jsx'
import { GameProvider } from './context/GameContext.jsx'

ReactDOM.createRoot(document.getElementById('root')).render(
  <React.StrictMode>
    <GameProvider>
      <App />
    </GameProvider>
  </React.StrictMode>
)
async function request(path, options = {}) {
  const response = await fetch(`/api${path}`, {
    headers: { 'Content-Type': 'application/json', ...(options.headers || {}) },
    ...options
  })
  let payload = null
  try {
    payload = await response.json()
  } catch {
    payload = null
  }
  if (!response.ok) {
    const error = new Error(payload?.error || `Request failed (${response.status})`)
    error.status = response.status
    throw error
  }
  return payload
}

export const api = {
  bootstrap: () => request('/bootstrap'),
  market: params => {
    const query = new URLSearchParams()
    Object.entries(params || {}).forEach(([key, value]) => {
      if (value !== undefined && value !== null && value !== '' && value !== 0 && value !== '0') {
        query.set(key, value)
      }
    })
    return request(`/market?${query.toString()}`)
  },
  buyPlayer: (playerId, teamId) =>
    request('/transfers/buy', {
      method: 'POST',
      body: JSON.stringify({ player_id: playerId, team_id: teamId })
    }),
  upgradeFacility: (teamId, facility) =>
    request('/facilities/upgrade', {
      method: 'POST',
      body: JSON.stringify({ team_id: teamId, facility })
    }),
  updateTactics: (teamId, tactics) =>
    request('/tactics', {
      method: 'POST',
      body: JSON.stringify({ team_id: teamId, ...tactics })
    }),
  simulateMatch: matchId =>
    request(`/matches/${matchId}/simulate`, {
      method: 'POST',
      body: JSON.stringify({})
    }),
  match: matchId => request(`/matches/${matchId}`)
}

import express from 'express'
import { existsSync } from 'node:fs'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'
import { seedDatabase } from './seed.js'
import {
  GameError,
  buyPlayer,
  getBootstrap,
  getMarket,
  getMatch,
  getMeta,
  saveTactics,
  simulateUserMatch,
  upgradeFacility
} from './game.js'
import { playerById, userTeam } from './store.js'

const __dirname = dirname(fileURLToPath(import.meta.url))
const app = express()
const PORT = Number(process.env.PORT || 3000)
const distDir = resolve(__dirname, '../dist')

const seeded = seedDatabase()
if (seeded.seeded) console.log('Seeded a fresh Touchline database.')
else console.log('Using existing Touchline database.')

app.disable('x-powered-by')
app.use(express.json({ limit: '1mb' }))
app.use('/api', (req, res, next) => {
  res.setHeader('Cache-Control', 'no-store')
  next()
})

const asyncRoute = handler => (req, res, next) => {
  try {
    handler(req, res, next)
  } catch (error) {
    next(error)
  }
}

app.get('/api/health', (req, res) => {
  res.json({ ok: true, service: 'touchline-api', time: new Date().toISOString() })
})

app.get('/api/bootstrap', asyncRoute((req, res) => {
  res.json(getBootstrap())
}))

app.get('/api/meta', (req, res) => {
  res.json(getMeta())
})

app.get('/api/market', asyncRoute((req, res) => {
  res.json(getMarket(req.query))
}))

app.get('/api/players/:id', asyncRoute((req, res) => {
  const player = playerById(req.params.id)
  if (!player) throw new GameError('Player not found', 404)
  res.json({ player })
}))

app.post('/api/transfers/buy', asyncRoute((req, res) => {
  const user = userTeam()
  const teamId = Number(req.body.team_id || user.id)
  if (teamId !== user.id) throw new GameError('You can only sign players for your own club', 403)
  const result = buyPlayer(Number(req.body.player_id), teamId)
  res.json(result)
}))

app.post('/api/facilities/upgrade', asyncRoute((req, res) => {
  const user = userTeam()
  const teamId = Number(req.body.team_id || user.id)
  if (teamId !== user.id) throw new GameError('You can only upgrade your own facilities', 403)
  const result = upgradeFacility(teamId, req.body.facility)
  res.json(result)
}))

app.post('/api/tactics', asyncRoute((req, res) => {
  const user = userTeam()
  const teamId = Number(req.body.team_id || user.id)
  if (teamId !== user.id) throw new GameError('You can only manage your own tactics', 403)
  const result = saveTactics(teamId, req.body)
  res.json(result)
}))

app.get('/api/matches/:id', asyncRoute((req, res) => {
  res.json({ match: getMatch(req.params.id) })
}))

app.post('/api/matches/:id/simulate', asyncRoute((req, res) => {
  res.json(simulateUserMatch(Number(req.params.id)))
}))

if (existsSync(distDir)) {
  app.use(express.static(distDir, {
    maxAge: '1h',
    setHeaders: (res, filePath) => {
      if (filePath.endsWith('index.html')) res.setHeader('Cache-Control', 'no-cache')
    }
  }))
  app.get('*', (req, res, next) => {
    if (req.path.startsWith('/api/')) return next()
    res.sendFile(join(distDir, 'index.html'))
  })
} else {
  app.get('/', (req, res) => {
    res.status(503).send('Frontend build not found. Run npm run build first.')
  })
}

app.use((req, res, next) => {
  if (req.path.startsWith('/api/')) return res.status(404).json({ error: 'Not found' })
  next()
})

app.use((error, req, res, next) => {
  if (res.headersSent) return next(error)
  const status = error instanceof GameError ? error.status : 500
  if (status >= 500) console.error(error)
  res.status(status).json({ error: error.message || 'Something went wrong' })
})

const server = app.listen(PORT, '0.0.0.0', () => {
  console.log(`Touchline '26 running on http://0.0.0.0:${PORT}`)
})

for (const signal of ['SIGTERM', 'SIGINT']) {
  process.on(signal, () => {
    server.close(() => process.exit(0))
  })
}
import { createContext, useCallback, useContext, useEffect, useMemo, useRef, useState } from 'react'
import { api } from '../api'

const GameContext = createContext(null)

const VIEW_KEY = 'touchline:view'

export const VIEWS = [
  { id: 'dashboard', label: 'Dashboard', eyebrow: 'Club overview' },
  { id: 'squad', label: 'Squad', eyebrow: 'First team' },
  { id: 'tactics', label: 'Tactics', eyebrow: 'Game model' },
  { id: 'matchday', label: 'Match Day', eyebrow: 'Live match' },
  { id: 'transfers', label: 'Transfer Market', eyebrow: 'Recruitment' },
  { id: 'facilities', label: 'Facilities', eyebrow: 'Club infrastructure' },
  { id: 'league', label: 'League', eyebrow: 'Standings & fixtures' }
]

export function GameProvider({ children }) {
  const [data, setData] = useState(null)
  const [loading, setLoading] = useState(true)
  const [refreshing, setRefreshing] = useState(false)
  const [error, setError] = useState(null)
  const [toasts, setToasts] = useState([])
  const [playerModal, setPlayerModal] = useState(null)
  const [view, setViewState] = useState(() => {
    const saved = localStorage.getItem(VIEW_KEY)
    return VIEWS.some(item => item.id === saved) ? saved : 'dashboard'
  })
  const mounted = useRef(true)
  const toastTimers = useRef(new Map())

  useEffect(() => {
    mounted.current = true
    return () => {
      mounted.current = false
      toastTimers.current.forEach(timer => clearTimeout(timer))
    }
  }, [])

  const notify = useCallback((message, tone = 'success') => {
    const id = `${Date.now()}-${Math.random().toString(16).slice(2)}`
    setToasts(current => [...current.slice(-2), { id, message, tone }])
    const timer = setTimeout(() => {
      setToasts(current => current.filter(toast => toast.id !== id))
      toastTimers.current.delete(id)
    }, 4800)
    toastTimers.current.set(id, timer)
  }, [])

  const dismissToast = useCallback(id => {
    setToasts(current => current.filter(toast => toast.id !== id))
    const timer = toastTimers.current.get(id)
    if (timer) clearTimeout(timer)
    toastTimers.current.delete(id)
  }, [])

  const refresh = useCallback(async ({ silent = false } = {}) => {
    if (!silent) setLoading(true)
    else setRefreshing(true)
    try {
      const payload = await api.bootstrap()
      if (!mounted.current) return payload
      setData(payload)
      setError(null)
      return payload
    } catch (err) {
      if (mounted.current) setError(err)
      if (!silent) notify(err.message || 'Could not load your club.', 'error')
      return null
    } finally {
      if (mounted.current) {
        setLoading(false)
        setRefreshing(false)
      }
    }
  }, [notify])

  useEffect(() => {
    refresh()
  }, [refresh])

  const setView = useCallback(id => {
    if (!VIEWS.some(item => item.id === id)) return
    setViewState(id)
    localStorage.setItem(VIEW_KEY, id)
    window.scrollTo({ top: 0, behavior: 'smooth' })
  }, [])

  const purchasePlayer = useCallback(async playerId => {
    try {
      const result = await api.buyPlayer(playerId, data?.user?.id)
      notify(result.message, 'success')
      await refresh({ silent: true })
      return result
    } catch (err) {
      notify(err.message || 'The transfer could not be completed.', 'error')
      throw err
    }
  }, [data?.user?.id, notify, refresh])

  const upgradeFacility = useCallback(async facility => {
    try {
      const result = await api.upgradeFacility(data?.user?.id, facility)
      notify(result.message, 'success')
      await refresh({ silent: true })
      return result
    } catch (err) {
      notify(err.message || 'Upgrade failed.', 'error')
      throw err
    }
  }, [data?.user?.id, notify, refresh])

  const updateTactics = useCallback(async tactics => {
    try {
      const result = await api.updateTactics(data?.user?.id, tactics)
      notify(result.message, 'success')
      await refresh({ silent: true })
      return result
    } catch (err) {
      notify(err.message || 'Could not save tactics.', 'error')
      throw err
    }
  }, [data?.user?.id, notify, refresh])

  const simulateMatch = useCallback(async matchId => {
    try {
      return await api.simulateMatch(matchId)
    } catch (err) {
      notify(err.message || 'The match could not be simulated.', 'error')
      throw err
    }
  }, [notify])

  const openPlayer = useCallback((player, options = {}) => {
    setPlayerModal({ player, ...options })
  }, [])

  const closePlayer = useCallback(() => setPlayerModal(null), [])

  const value = useMemo(() => ({
    data,
    loading,
    refreshing,
    error,
    toasts,
    view,
    setView,
    refresh,
    notify,
    dismissToast,
    purchasePlayer,
    upgradeFacility,
    updateTactics,
    simulateMatch,
    playerModal,
    openPlayer,
    closePlayer
  }), [
    data, loading, refreshing, error, toasts, view, setView, refresh, notify, dismissToast,
    purchasePlayer, upgradeFacility, updateTactics, simulateMatch, playerModal, openPlayer, closePlayer
  ])

  return <GameContext.Provider value={value}>{children}</GameContext.Provider>
}

export function useGame() {
  const context = useContext(GameContext)
  if (!context) throw new Error('useGame must be used inside GameProvider')
  return context
}

